        source=A/'data/local/tmp/hepta-phone-local-v150-r1'/('hepta-native-guard-'+a.name)
        b,m=read(source,32*1024*1024);need(len(b)==a.bytes and sha(b)==a.sha256,'actual pushed bytes')
        target=G/'native-guard-staging-r10-r1'
