        target=home/('ROOT-'+a.phase.upper()+'-PLAN.json');deadline=time.monotonic()+(60 if a.phase=='setup' else 25)
        while True:
            try:target.lstat();break
            except FileNotFoundError as e:need(e.errno==2,'plan read error')
